import{_ as e,a0 as t,w as o,s as r,ao as c,I as p,x as a,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上使用 kill 和 killall 命令來管理進程 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 kill 和 killall 命令來管理進程 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 kill 和 killall 命令來管理進程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 kill 和 killall 命令來管理進程 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20200127 Managing processes on Linux with kill and killall","title":"在 Linux 上使用 kill 和 killall 命令來管理進程","tag":"202103","desc":""},"relativePath":"202103/20200127 Managing processes on Linux with kill and killall.md","filePath":"[post].md"}'),d={name:"202103/20200127 Managing processes on Linux with kill and killall.md"};function h(u,s,k,g,m,b){const n=t("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="在-linux-上使用-kill-和-killall-命令來管理進程" tabindex="-1">在 Linux 上使用 kill 和 killall 命令來管理進程 <a class="header-anchor" href="#在-linux-上使用-kill-和-killall-命令來管理進程" aria-label="Permalink to “在 Linux 上使用 kill 和 killall 命令來管理進程”">​</a></h1><blockquote><p>瞭解如何使用 ps、kill 和 killall 命令來終止進程並回收系統資源。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202103/18/230625q6g65gz6ugdk8ygr.jpg" alt=""></p><p>在 Linux 中，每個程序和<ruby>守護程序<rt>daemon</rt></ruby>都是一個“<ruby>進程<rt>process</rt></ruby>”。 大多數進程代表一個正在運行的程序。而另外一些程序可以派生出其他進程，比如説它會偵聽某些事件的發生，然後對其做出響應。並且每個進程都需要一定的內存和處理能力。你運行的進程越多，所需的內存和 CPU 使用週期就越多。在老式電腦（例如我使用了 7 年的筆記本電腦）或輕量級計算機（例如樹莓派）上，如果你關注過後台運行的進程，就能充分利用你的系統。</p><p>你可以使用 <code>ps</code> 命令來查看正在運行的進程。你通常會使用 <code>ps</code> 命令的參數來顯示出更多的輸出信息。我喜歡使用 <code>-e</code> 參數來查看每個正在運行的進程，以及 <code>-f</code> 參數來獲得每個進程的全部細節。以下是一些例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps</span></span>
<span class="line"><span>    PID TTY          TIME CMD</span></span>
<span class="line"><span>  88000 pts/0    00:00:00 bash</span></span>
<span class="line"><span>  88052 pts/0    00:00:00 ps</span></span>
<span class="line"><span>  88053 pts/0    00:00:00 head</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -e | head</span></span>
<span class="line"><span>    PID TTY          TIME CMD</span></span>
<span class="line"><span>      1 ?        00:00:50 systemd</span></span>
<span class="line"><span>      2 ?        00:00:00 kthreadd</span></span>
<span class="line"><span>      3 ?        00:00:00 rcu_gp</span></span>
<span class="line"><span>      4 ?        00:00:00 rcu_par_gp</span></span>
<span class="line"><span>      6 ?        00:00:02 kworker/0:0H-events_highpri</span></span>
<span class="line"><span>      9 ?        00:00:00 mm_percpu_wq</span></span>
<span class="line"><span>     10 ?        00:00:01 ksoftirqd/0</span></span>
<span class="line"><span>     11 ?        00:00:12 rcu_sched</span></span>
<span class="line"><span>     12 ?        00:00:00 migration/0</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | head</span></span>
<span class="line"><span>UID          PID    PPID  C STIME TTY          TIME CMD</span></span>
<span class="line"><span>root           1       0  0 13:51 ?        00:00:50 /usr/lib/systemd/systemd --switched-root --system --deserialize 36</span></span>
<span class="line"><span>root           2       0  0 13:51 ?        00:00:00 [kthreadd]</span></span>
<span class="line"><span>root           3       2  0 13:51 ?        00:00:00 [rcu_gp]</span></span>
<span class="line"><span>root           4       2  0 13:51 ?        00:00:00 [rcu_par_gp]</span></span>
<span class="line"><span>root           6       2  0 13:51 ?        00:00:02 [kworker/0:0H-kblockd]</span></span>
<span class="line"><span>root           9       2  0 13:51 ?        00:00:00 [mm_percpu_wq]</span></span>
<span class="line"><span>root          10       2  0 13:51 ?        00:00:01 [ksoftirqd/0]</span></span>
<span class="line"><span>root          11       2  0 13:51 ?        00:00:12 [rcu_sched]</span></span>
<span class="line"><span>root          12       2  0 13:51 ?        00:00:00 [migration/0]</span></span></code></pre></div><p>最後的例子顯示最多的細節。在每一行，<code>UID</code>（用户 ID）顯示了該進程的所有者。<code>PID</code>（進程 ID）代表每個進程的數字 ID，而 <code>PPID</code>（父進程 ID）表示其父進程的數字 ID。在任何 Unix 系統中，進程是從 1 開始編號，是內核啓動後運行的第一個進程。在這裏，<code>systemd</code> 是第一個進程，它催生了 <code>kthreadd</code>，而 <code>kthreadd</code> 還創建了其他進程，包括 <code>rcu_gp</code>、<code>rcu_par_gp</code> 等一系列進程。</p><h3 id="使用-kill-命令來管理進程" tabindex="-1">使用 kill 命令來管理進程 <a class="header-anchor" href="#使用-kill-命令來管理進程" aria-label="Permalink to “使用 kill 命令來管理進程”">​</a></h3><p>系統會處理大多數後台進程，所以你不需要操心這些進程。你只需要關注那些你所運行的應用創建的進程。雖然許多應用一次只運行一個進程（如音樂播放器、終端模擬器或遊戲等），但其他應用則可能創建後台進程。其中一些應用可能當你退出後還在後台運行，以便下次你使用的時候能快速啓動。</p><p>當我運行 Chromium（作為谷歌 Chrome 瀏覽器所基於的開源項目）時，進程管理便成了問題。 Chromium 在我的筆記本電腦上運行非常吃力，併產生了許多額外的進程。現在我僅打開五個選項卡，就能看到這些 Chromium 進程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | fgrep chromium</span></span>
<span class="line"><span>jhall      66221   [...]  /usr/lib64/chromium-browser/chromium-browser [...]</span></span>
<span class="line"><span>jhall      66230   [...]  /usr/lib64/chromium-browser/chromium-browser [...]</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>jhall      66861   [...]  /usr/lib64/chromium-browser/chromium-browser [...]</span></span>
<span class="line"><span>jhall      67329   65132  0 15:45 pts/0    00:00:00 grep -F chromium</span></span></code></pre></div><p>我已經省略一些行，其中有 20 個 Chromium 進程和一個正在搜索 “chromium&quot; 字符的 <code>grep</code> 進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | fgrep chromium | wc -l</span></span>
<span class="line"><span>21</span></span></code></pre></div><p>但是在我退出 Chromium 之後，這些進程仍舊運行。如何關閉它們並回收這些進程佔用的內存和 CPU 呢？</p><p><code>kill</code> 命令能讓你終止一個進程。在最簡單的情況下，你告訴 <code>kill</code> 命令終止你想終止的進程的 PID。例如，要終止這些進程，我需要對 20 個 Chromium 進程 ID 都執行 <code>kill</code> 命令。一種方法是使用命令列獲取 Chromium 的 PID，而另一種方法針對該列表運行 <code>kill</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | fgrep /usr/lib64/chromium-browser/chromium-browser | awk &#39;{print $2}&#39;</span></span>
<span class="line"><span>66221</span></span>
<span class="line"><span>66230</span></span>
<span class="line"><span>66239</span></span>
<span class="line"><span>66257</span></span>
<span class="line"><span>66262</span></span>
<span class="line"><span>66283</span></span>
<span class="line"><span>66284</span></span>
<span class="line"><span>66285</span></span>
<span class="line"><span>66324</span></span>
<span class="line"><span>66337</span></span>
<span class="line"><span>66360</span></span>
<span class="line"><span>66370</span></span>
<span class="line"><span>66386</span></span>
<span class="line"><span>66402</span></span>
<span class="line"><span>66503</span></span>
<span class="line"><span>66539</span></span>
<span class="line"><span>66595</span></span>
<span class="line"><span>66734</span></span>
<span class="line"><span>66848</span></span>
<span class="line"><span>66861</span></span>
<span class="line"><span>69702</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ps -ef | fgrep /usr/lib64/chromium-browser/chromium-browser | awk &#39;{print $2}&#39; &gt; /tmp/pids</span></span>
<span class="line"><span>$ kill $(cat /tmp/pids)</span></span></code></pre></div><p>最後兩行是關鍵。第一個命令列為 Chromium 瀏覽器生成一個進程 ID 列表。第二個命令列針對該進程 ID 列表運行 <code>kill</code> 命令。</p><h3 id="介紹-killall-命令" tabindex="-1">介紹 killall 命令 <a class="header-anchor" href="#介紹-killall-命令" aria-label="Permalink to “介紹 killall 命令”">​</a></h3><p>一次終止多個進程有個更簡單方法，使用 <code>killall</code> 命令。你或許可以根據名稱猜測出，<code>killall</code> 會終止所有與該名字匹配的進程。這意味着我們可以使用此命令來停止所有流氓 Chromium 進程。這很簡單：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ killall /usr/lib64/chromium-browser/chromium-browser</span></span></code></pre></div><p>但是要小心使用 <code>killall</code>。該命令能夠終止與你所給出名稱相匹配的所有進程。這就是為什麼我喜歡先使用 <code>ps -ef</code> 命令來檢查我正在運行的進程，然後針對要停止的命令的準確路徑運行 <code>killall</code>。</p><p>你也可以使用 <code>-i</code> 或 <code>--interactive</code> 參數，來讓 <code>killkill</code> 在停止每個進程之前提示你。</p><p><code>killall</code> 還支持使用 <code>-o</code> 或 <code>--older-than</code> 參數來查找比特定時間更早的進程。例如，如果你發現了一組已經運行了好幾天的惡意進程，這將會很有幫助。又或是，你可以查找比特定時間更晚的進程，例如你最近啓動的失控進程。使用 <code>-y</code> 或 <code>--young-than</code> 參數來查找這些進程。</p><h3 id="其他管理進程的方式" tabindex="-1">其他管理進程的方式 <a class="header-anchor" href="#其他管理進程的方式" aria-label="Permalink to “其他管理進程的方式”">​</a></h3><p>進程管理是系統維護重要的一部分。在我作為 Unix 和 Linux 系統管理員的早期職業生涯中，殺死非法作業的能力是保持系統正常運行的關鍵。在如今，你可能不需要親手在 Linux 上的終止流氓進程，但是知道 <code>kill</code> 和 <code>killall</code> 能夠在最終出現問題時為你提供幫助。</p><p>你也能尋找其他方式來管理進程。在我這個案例中，我並不需要在我退出瀏覽器後，使用 <code>kill</code> 或 <code>killall</code> 來終止後台 Chromium 進程。在 Chromium 中有個簡單設置就可以進行控制：</p><p><img src="https://opensource.com/sites/default/files/uploads/chromium-settings-continue-running.png" alt="Chromium background processes setting" title="Chromium background processes setting"></p><p>不過，始終關注系統上正在運行哪些進程，並且在需要的時候進行干預是一個明智之舉。</p><hr>`,31)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),l(n,{href:"https://opensource.com/article/20/1/linux-kill-killall"},{default:i(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/20/1/linux-kill-killall",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),l(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[a("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),l(n,{href:"https://github.com/wyxplus"},{default:i(()=>[...s[4]||(s[4]=[a("wyxplus",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),l(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const y=e(d,[["render",h]]);export{x as __pageData,y as default};
